`import SwiftUI

struct ContentView: View {
    @State private var FinnishedWorkout: Bool = false
    @State private var progress = 0.0

    var body: some View {

        VStack(spacing : 10) {
            HStack{
                Toggle("Workout", isOn: $FinnishedWorkout)
                    .padding(40)
                Text(FinnishedWorkout ? "YOU DID IT" : "Keep Going")
                    .padding(20)
            }
            Divider()

            ProgressView(value: progress)
            Button("+1 Rep"){

                if progress < 1.0 {
                    progress += 0.01

                    if progress >= 1.0{
                        progress = 0.01

                                    //change both the bottom assets to change how much the button moves

                                }
                            }
                        }
                        Text("Progress:\(progress.formatted(.percent))")`
